namespace Ada {
 public sealed partial class AdaWindow {
  StackPanel miniInfo;Grid headerWater;StackPanel audioBars;readonly double[] peakHistory=new double[9];readonly DispatcherTimer peakTick=new DispatcherTimer(DispatcherPriority.Background){Interval=TimeSpan.FromMilliseconds(40)};bool waterBannerVisible;int waterMotionGeneration,quietPeaks;string lastTrackKey="";double injectedPeak=-1;int trackAnimationCount;
  void InitCompactEffects(){peakTick.Tick+=delegate{double peak=testing?Math.Max(0,injectedPeak):audio.Peak();DrawPeak(peak);quietPeaks=peak<.001?quietPeaks+1:0;peakTick.Interval=TimeSpan.FromMilliseconds(quietPeaks>35?180:40);};}
  void BuildHeaderEffects(Grid left){waterBannerVisible=false;
   audioBars=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,Height=25,IsHitTestVisible=false};for(int i=0;i<9;i++){var bar=new Rectangle{Width=3,Height=3,RadiusX=1.5,RadiusY=1.5,Margin=new Thickness(2,0,2,0),VerticalAlignment=VerticalAlignment.Center};bar.SetResourceReference(Shape.FillProperty,"Accent");audioBars.Children.Add(bar);}Grid.SetColumn(audioBars,1);header.Children.Add(audioBars);
   headerWater=new Grid{Visibility=Visibility.Collapsed,Opacity=0,Cursor=System.Windows.Input.Cursors.Hand,Background=Brushes.Transparent};headerWater.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(33)});headerWater.ColumnDefinitions.Add(new ColumnDefinition());headerWater.Children.Add(Glyph("drop",24,"Accent"));var text=new StackPanel{VerticalAlignment=VerticalAlignment.Center};text.Children.Add(Label("Su zamanı",15,true));text.Children.Add(Label("Bir bardak iç.",12,false,"Muted"));Grid.SetColumn(text,1);headerWater.Children.Add(text);Grid.SetColumn(headerWater,0);Grid.SetColumnSpan(headerWater,2);left.Children.Add(headerWater);headerWater.MouseLeftButtonUp+=delegate(object sender,System.Windows.Input.MouseButtonEventArgs e){e.Handled=true;DismissNotice();Navigate("water");};
  }
  void UpdateVisualizerState(bool clockShowing){if(audioBars==null)return;bool visible=route==""&&!edgeHidden&&!clockShowing;audioBars.Visibility=visible?Visibility.Visible:Visibility.Collapsed;bool running=visible&&Media.Playing&&MotionAllowed;if(running&&!testing)peakTick.Start();else{peakTick.Stop();DrawPeak(0,false);}}
  void DrawPeak(double peak,bool animate=true){if(audioBars==null)return;if(!animate&&peak==0)Array.Clear(peakHistory,0,peakHistory.Length);for(int i=peakHistory.Length-1;i>0;i--)peakHistory[i]=peakHistory[i-1];peakHistory[0]=Math.Pow(Math.Max(0,Math.Min(1,peak)),.55);for(int i=0;i<audioBars.Children.Count;i++){var bar=(Rectangle)audioBars.Children[i];double value=peakHistory[Math.Abs(i-4)*2];double height=3+value*(22-Math.Abs(i-4)*2);if(!animate||!MotionAllowed){bar.BeginAnimation(FrameworkElement.HeightProperty,null);bar.Height=height;}else{var a=new DoubleAnimation(bar.ActualHeight>0?bar.ActualHeight:3,height,TimeSpan.FromMilliseconds(85)){EasingFunction=new QuadraticEase{EasingMode=EasingMode.EaseOut},FillBehavior=FillBehavior.Stop};bar.Height=height;Timeline.SetDesiredFrameRate(a,TargetFps);bar.BeginAnimation(FrameworkElement.HeightProperty,a);}}}
  void UpdateCompactEffects(){UpdateVisualizerState(ClockVisible||(clockMotionRunning&&clock.Visibility==Visibility.Visible));if(headerWater==null)return;bool show=route==""&&currentNotice!=null&&currentNotice.Kind=="water";if(show==waterBannerVisible)return;waterBannerVisible=show;FadeWaterArtwork(show);int generation=++waterMotionGeneration;headerWater.BeginAnimation(UIElement.OpacityProperty,null);var old=headerWater.RenderTransform as TranslateTransform;if(old!=null)old.BeginAnimation(TranslateTransform.YProperty,null);if(show){headerWater.Visibility=Visibility.Visible;miniInfo.BeginAnimation(UIElement.OpacityProperty,null);miniInfo.Opacity=0;}if(!MotionAllowed||!IsLoaded){headerWater.Opacity=show?1:0;headerWater.Visibility=show?Visibility.Visible:Visibility.Collapsed;miniInfo.Opacity=show?0:1;return;}var shift=new TranslateTransform(0,show?5:0);headerWater.RenderTransform=shift;var a=new DoubleAnimation(show?0:headerWater.Opacity,show?1:0,TimeSpan.FromMilliseconds(show?260:180)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut},FillBehavior=FillBehavior.Stop};Timeline.SetDesiredFrameRate(a,TargetFps);headerWater.Opacity=show?1:0;var slide=new DoubleAnimation(show?5:0,show?0:-5,TimeSpan.FromMilliseconds(260)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut},FillBehavior=FillBehavior.Stop};Timeline.SetDesiredFrameRate(slide,TargetFps);a.Completed+=delegate{if(generation!=waterMotionGeneration)return;headerWater.BeginAnimation(UIElement.OpacityProperty,null);shift.BeginAnimation(TranslateTransform.YProperty,null);headerWater.RenderTransform=Transform.Identity;if(!show){headerWater.Visibility=Visibility.Collapsed;AnimateTrackInk(false);}};headerWater.BeginAnimation(UIElement.OpacityProperty,a);shift.BeginAnimation(TranslateTransform.YProperty,slide);}
  void FadeWaterArtwork(bool hide){if(miniCover==null)return;double from=miniCover.Opacity;miniCover.BeginAnimation(UIElement.OpacityProperty,null);miniCover.Opacity=hide?0:1;if(!MotionAllowed||!IsLoaded)return;var fade=new DoubleAnimation(from,hide?0:1,TimeSpan.FromMilliseconds(hide?160:220)){FillBehavior=FillBehavior.Stop};Timeline.SetDesiredFrameRate(fade,TargetFps);fade.Completed+=delegate{miniCover.BeginAnimation(UIElement.OpacityProperty,null);};miniCover.BeginAnimation(UIElement.OpacityProperty,fade);}
  void DetectTrackTransition(){string key=Media.Title+"\n"+Media.Artist;if(key==lastTrackKey)return;bool change=lastTrackKey.Length>1&&!String.IsNullOrWhiteSpace(Media.Title);lastTrackKey=key;if(change&&route==""&&!waterBannerVisible)AnimateTrackInk(true);}
  void AnimateTrackInk(bool cover){if(miniInfo==null)return;miniInfo.BeginAnimation(UIElement.OpacityProperty,null);var old=miniInfo.RenderTransform as TranslateTransform;if(old!=null)old.BeginAnimation(TranslateTransform.YProperty,null);miniInfo.Opacity=1;if(!MotionAllowed)return;trackAnimationCount++;var shift=new TranslateTransform(0,5);miniInfo.RenderTransform=shift;var move=new DoubleAnimation(5,0,TimeSpan.FromMilliseconds(300)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut},FillBehavior=FillBehavior.Stop};var fade=new DoubleAnimation(.1,1,TimeSpan.FromMilliseconds(240)){FillBehavior=FillBehavior.Stop};Timeline.SetDesiredFrameRate(move,TargetFps);Timeline.SetDesiredFrameRate(fade,TargetFps);move.Completed+=delegate{if(miniInfo.RenderTransform==shift){shift.BeginAnimation(TranslateTransform.YProperty,null);miniInfo.RenderTransform=Transform.Identity;}};fade.Completed+=delegate{miniInfo.BeginAnimation(UIElement.OpacityProperty,null);};shift.BeginAnimation(TranslateTransform.YProperty,move);miniInfo.BeginAnimation(UIElement.OpacityProperty,fade);if(cover){var artFade=new DoubleAnimation(.3,1,TimeSpan.FromMilliseconds(280)){FillBehavior=FillBehavior.Stop};Timeline.SetDesiredFrameRate(artFade,TargetFps);artFade.Completed+=delegate{miniCover.BeginAnimation(UIElement.OpacityProperty,null);};miniCover.BeginAnimation(UIElement.OpacityProperty,artFade);}}
  void StopCompactEffects(){peakTick.Stop();if(audioBars!=null)foreach(Rectangle bar in audioBars.Children)bar.BeginAnimation(FrameworkElement.HeightProperty,null);if(headerWater!=null){headerWater.BeginAnimation(UIElement.OpacityProperty,null);var t=headerWater.RenderTransform as TranslateTransform;if(t!=null)t.BeginAnimation(TranslateTransform.YProperty,null);}if(miniInfo!=null){miniInfo.BeginAnimation(UIElement.OpacityProperty,null);var t=miniInfo.RenderTransform as TranslateTransform;if(t!=null)t.BeginAnimation(TranslateTransform.YProperty,null);}if(miniCover!=null)miniCover.BeginAnimation(UIElement.OpacityProperty,null);}
